def gf4_add(a, b):
    return a ^ b

def gf4_mul(a, b):
    mul_table = [
        [0, 0, 0, 0],
        [0, 1, 2, 3],
        [0, 2, 3, 1],
        [0, 3, 1, 2]
    ]
    return mul_table[a][b]

points = [(x, y) for x in range(4) for y in range(4)]
point_idx = {p: i for i, p in enumerate(points)}

blocks = []
for m in range(4):
    for c in range(4):
        block = []
        for x in range(4):
            y = gf4_add(gf4_mul(m, x), c)
            block.append(point_idx[(x, y)])
        blocks.append(sorted(block))

for c in range(4):
    block = []
    for y in range(4):
        block.append(point_idx[(c, y)])
    blocks.append(sorted(block))

blocks_3 = blocks + blocks + blocks

v, b = 16, 60
matrix = [[0]*b for _ in range(v)]
for j, block in enumerate(blocks_3):
    for i in block:
        matrix[i][j] = 1

flat = [matrix[i][j] for i in range(v) for j in range(b)]
print(flat)
